insert into tricks (id, given_name, technical_name, difficulty_tier, date_submitted, date_performed, original_performer, prerequisite_trick_ids, base_trick_ids, description, tips, video_link, video_start, video_end, start_position_id, end_position_id, status, flags) overriding system value values (13, 'Front Nirvana', '360 Front Sofa Roll to Feet', 17, '2025-03-08T10:19:01+00:00', '2023-08-23', 'Ian Eisenberg', '{}', '{}', 'From Sofa you grab the line with both hands on the side and initiate a roll to the front. You immediately go into Belly and keep rolling but then add another 180, regrab one hand and land in Expo.', null, 'https://www.instagram.com/p/CwTGyDcMBRb/', null, null, 11, 5, 1, 0);
