insert into tricks (id, given_name, technical_name, difficulty_tier, date_submitted, date_performed, original_performer, prerequisite_trick_ids, base_trick_ids, description, tips, video_link, video_start, video_end, start_position_id, end_position_id, status, flags) overriding system value values (19, 'Doombringer', 'Panic Roll Rewind to Feet', 23, '2025-11-01T20:15:36+00:00', '2025-08-30', 'Jordan Robinson', '{185,260,176}', '{}', 'Do a Panic Roll and set up for a Darkside Roll out of it. Similar to a Bangarang but starting with a Panic Roll.', 'The Panic Roll should be as fast as you can muster without the rotational force opening up your legs so that you can''t get them on the line. I try to aim to get my feet on the line as quickly as possible so that I have something to pull against for the second half. Hand positioning for the Panic Roll is super wide so that there''s space to fit the legs in between them.
