insert into tricks (id, given_name, technical_name, difficulty_tier, date_submitted, date_performed, original_performer, prerequisite_trick_ids, base_trick_ids, description, tips, video_link, video_start, video_end, start_position_id, end_position_id, status, flags) overriding system value values (72, 'Space Korean', 'Space Orbital Korean to Korean', 23, '2025-03-09T08:48:06+00:00', '2025-01-05', 'Tim Odermatt', '{}', '{}', 'From korean change your leg to butt and from there let the line go to do a space orbital. Use your leg to catch the line in korean.', null, 'https://www.instagram.com/reel/DEcYgbmo4Sp/', null, null, 6, 6, 1, 0);
insert into tricks (id, given_name, technical_name, difficulty_tier, date_submitted, date_performed, original_performer, prerequisite_trick_ids, base_trick_ids, description, tips, video_link, video_start, video_end, start_position_id, end_position_id, status, flags) overriding system value values (73, 'Korean 180', null, 2, '2026-04-25T21:27:54.76891+00:00', null, null, '{}', '{}', 'From Korean grab the line with both hands in front of you. Towards the top of the bounce swing one leg over the line so that you end up in the belly position. Then swing the other leg over the line so that you are back in Korean, only facing the other direction this time.', 'If it is hard to get the first leg over the line, try starting later in the bounce. As a preexercise you can practice the transition from Korean to Belly and vice verse in isolation before putting them together.', 'https://www.youtube.com/watch?v=3GWR5ZzSRBg', null, null, 6, 6, 1, 1);
insert into tricks (id, given_name, technical_name, difficulty_tier, date_submitted, date_performed, original_performer, prerequisite_trick_ids, base_trick_ids, description, tips, video_link, video_start, video_end, start_position_id, end_position_id, status, flags) overriding system value values (74, 'Tortuga Koreana / korean turtle', 'Backbounce 360 spin to korean', 17, '2025-03-10T11:20:10+00:00', '2023-04-12', 'Gon Caturelli', '{}', '{}', 'From backbounce grab the line behind your head and do a 360 spin to end in korean.', null, 'https://www.instagram.com/reel/Cq8MTfKum12/', null, null, 1, 6, 1, 0);
insert into tricks (id, given_name, technical_name, difficulty_tier, date_submitted, date_performed, original_performer, prerequisite_trick_ids, base_trick_ids, description, tips, video_link, video_start, video_end, start_position_id, end_position_id, status, flags) overriding system value values (76, 'Fire Mind', 'Back Korean 180 roll to Nevermid', 17, '2025-12-25T16:41:57+00:00', '2025-12-22', 'José Perales', '{}', '{}', 'From Korean, rotate backward, taking the line, making a roll, and following that roll into the Nevermid stance, ending in feet.', 'Step on it hard', null, null, null, 6, 8, 1, 0);
insert into tricks (id, given_name, technical_name, difficulty_tier, date_submitted, date_performed, original_performer, prerequisite_trick_ids, base_trick_ids, description, tips, video_link, video_start, video_end, start_position_id, end_position_id, status, flags) overriding system value values (78, 'Batman', '360 Rocket (over Bat-Hang)', 10, '2025-03-05T17:28:39+00:00', '2022-08-25', 'Ian Eisenberg', '{}', '{}', 'You drop to Rocket slightly uncentered such that you can get some momentum by swinging to one side. From there you use the momentum to swing your legs to the other side and all the way up to hook the line with both feet (the Bat-Hang position), you let go with your hands and do a 360 under the line by regrabbing the line on the other side of your feet. Unhook your feet and land back in Rocket.', null, 'https://www.instagram.com/p/ChsA7RvrV7m/', null, null, 9, 9, 1, 0);
insert into tricks (id, given_name, technical_name, difficulty_tier, date_submitted, date_performed, original_performer, prerequisite_trick_ids, base_trick_ids, description, tips, video_link, video_start, video_end, start_position_id, end_position_id, status, flags) overriding system value values (79, 'A Chuparla', 'Back Shapeshifter', 12, '2025-03-05T17:40:13+00:00', '2022-10-24', 'Sakalomo', '{}', '{}', 'Bounce hard, almost at the top of the bounce throw yourself backwards and do a backflip without touching the line. Put your hands up and grab the line to end in the rocket position.', null, 'https://www.instagram.com/reel/CkGq5w3unmy/', null, null, 5, 9, 1, 0);
insert into tricks (id, given_name, technical_name, difficulty_tier, date_submitted, date_performed, original_performer, prerequisite_trick_ids, base_trick_ids, description, tips, video_link, video_start, video_end, start_position_id, end_position_id, status, flags) overriding system value values (80, 'Darth Maul', '180 Exposure Backflip to Rocket', 13, '2025-03-08T10:13:50+00:00', '2023-05-04', 'Logan Henning', '{}', '{}', 'From Expo you lean back as much as possible (as if you would do a back bridge) until you reach the line with one hand. Spin 180 and grab the line with the second hand, so that you end up in Rocket.', null, 'https://www.instagram.com/p/Cr2RxoYLEPT/', null, null, 5, 9, 1, 0);
