insert into tricks (id, given_name, technical_name, difficulty_tier, date_submitted, date_performed, original_performer, prerequisite_trick_ids, base_trick_ids, description, tips, video_link, video_start, video_end, start_position_id, end_position_id, status, flags) overriding system value values (89, 'Space eclipse to sofa', 'Eclipse without touching the line to sofa', 23, '2025-03-08T09:04:07+00:00', '2024-09-08', 'Sakalomo', '{}', '{}', 'Do a eclipse bot don’t use your hands to move the line, let the high tension bring the line back down and go to sofa.', 'You need the right setup, some bungees and a lot of tensión on the line.', 'https://www.instagram.com/reel/C_p2waaMiEy/', null, null, 13, 11, 1, 0);
insert into tricks (id, given_name, technical_name, difficulty_tier, date_submitted, date_performed, original_performer, prerequisite_trick_ids, base_trick_ids, description, tips, video_link, video_start, video_end, start_position_id, end_position_id, status, flags) overriding system value values (90, 'Catwheel', 'Cartwheel from Sofa to Sofa', 11, '2023-07-28T14:24:15+00:00', '2023-05-27', 'Tomáš Michel', '{}', '{}', 'Starting in sofa with ring front you, catch the line on your side and in 75% of way up in the bounce push to handstand to you are fully extended on the top of the bounce, after you continue in motion to side landing in sofa.', 'Play with handstand from sofa and drop it to leashfall to get feeling of this position and land trick in side rotation.', 'https://www.instagram.com/reel/CvPiE2goN-l/', null, null, 11, 11, 1, 1);
