insert into tricks (id, given_name, technical_name, difficulty_tier, date_submitted, date_performed, original_performer, prerequisite_trick_ids, base_trick_ids, description, tips, video_link, video_start, video_end, start_position_id, end_position_id, status, flags) overriding system value values (123, 'Chill Roll', 'Backbounce roll half spiral to feet', 17, '2025-03-05T17:05:22+00:00', '2022-01-19', 'Sakalomo', '{}', '{}', 'Start from backbounce and grab the line with one hand. Before the top of the bounce throw yourself to the side of the hand that grabs the line. Do a roll below the line, take with both hands and put your feet.', 'Timing is key. When you throw yourself think of kicking up with your knees/feet to initiate the rotation.', 'https://www.instagram.com/reel/CY6eIm2K4_M/', null, null, 1, 13, 1, 1);
