insert into tricks (id, given_name, technical_name, difficulty_tier, date_submitted, date_performed, original_performer, prerequisite_trick_ids, base_trick_ids, description, tips, video_link, video_start, video_end, start_position_id, end_position_id, status, flags) overriding system value values (126, 'Back Drop', null, 8, '2022-01-01T00:00:00+00:00', null, null, '{}', '{}', 'From standing on the line you let the line come towards your body on the top of the bounce and when your butt is on the line, slide your feet off the line and lean all the way back to land in Back.', 'Practice leaning back from Korean to Back, and then combine the motion with a Korean bounce.
