insert into tricks (id, given_name, technical_name, difficulty_tier, date_submitted, date_performed, original_performer, prerequisite_trick_ids, base_trick_ids, description, tips, video_link, video_start, video_end, start_position_id, end_position_id, status, flags) overriding system value values (204, 'Rocket Mount', null, 12, '2022-01-01T00:00:00+00:00', '2017-01-01', 'Samuel Volery', '{395,156}', '{}', 'At the bottom of the bounce, kick your legs to the back, immediately afterwards kick them to the front again. Then do a final kick to the back while pulling yourself up in front of the line, then push it down at the top and put your feet on the line.', 'Get some momentum with your legs in the bottom part of the bounce. As soon as you are weightless pull the line below your feet.; This trick doesn''t require as much strength as you would think! It''s all about getting enough momentum with your legs.; If you can''t hold the bounce in the Rocket position try again with less bounce.', 'https://youtu.be/zSfwTW4vJas', null, null, 9, 5, 1, 1);
