insert into tricks (id, given_name, technical_name, difficulty_tier, date_submitted, date_performed, original_performer, prerequisite_trick_ids, base_trick_ids, description, tips, video_link, video_start, video_end, start_position_id, end_position_id, status, flags) overriding system value values (307, 'Frontflop', 'Front Roll from Feet', 14, '2022-01-01T00:00:00+00:00', '2017-01-01', 'Guillaume Fontaine', '{}', '{}', 'From Standing grab the line as in a Kamikaze, but then roll over your back and land in Korean.', 'Thread your arm through the leash so it is not wrapped around your shoulder.', 'https://youtu.be/n2z3IyeQSj4?t=41', 41, 44, 13, 6, 1, 0);
