insert into tricks (id, given_name, technical_name, difficulty_tier, date_submitted, date_performed, original_performer, prerequisite_trick_ids, base_trick_ids, description, tips, video_link, video_start, video_end, start_position_id, end_position_id, status, flags) overriding system value values (317, 'Lando', 'Leash Orbital', 17, '2026-04-25T21:28:03.559615+00:00', '2022-07-01', 'Davis Hermes', '{309}', '{309}', 'Do an Orbital, but grabing the leash instead of the line.', null, 'https://www.instagram.com/p/CgrrMmhgxhF/', null, null, 13, 6, 1, 0);
insert into tricks (id, given_name, technical_name, difficulty_tier, date_submitted, date_performed, original_performer, prerequisite_trick_ids, base_trick_ids, description, tips, video_link, video_start, video_end, start_position_id, end_position_id, status, flags) overriding system value values (321, 'Panic', 'Sofa 270 to Korean', 3, '2022-01-01T00:00:00+00:00', null, null, '{}', '{}', 'From Sofa you start a 180 FS spin, grab the line on your side with both hands and swing the far leg over the line to land in Korean.', 'Keep your center of gravity above the line.', 'https://www.youtube.com/watch?v=12HbVhoFloM', null, null, 11, 6, 1, 1);
insert into tricks (id, given_name, technical_name, difficulty_tier, date_submitted, date_performed, original_performer, prerequisite_trick_ids, base_trick_ids, description, tips, video_link, video_start, video_end, start_position_id, end_position_id, status, flags) overriding system value values (322, 'Panic Roll', 'Sofa 270 Korean Roll', 5, '2022-01-01T00:00:00+00:00', null, 'Jediah Doohan', '{}', '{}', 'Sit in Sofa position grab the line to the side of you with hands facing behind you. On the way up in the bounce dive down where your hands are and roll around the line. Land in Korean or Chest. Essentially you perform a 270 spin combined with a roll around the line.', 'It helps to separately practice the spin of the leg (Panic) and the roll around the line and then work to combine both at the same time.', 'https://www.youtube.com/watch?v=12HbVhoFloM', null, null, 11, 6, 1, 1);
insert into tricks (id, given_name, technical_name, difficulty_tier, date_submitted, date_performed, original_performer, prerequisite_trick_ids, base_trick_ids, description, tips, video_link, video_start, video_end, start_position_id, end_position_id, status, flags) overriding system value values (323, 'Half Front Roll', null, 8, '2022-01-01T00:00:00+00:00', null, null, '{}', '{}', 'Arrange the leash such that it''s hanging down on the side of the shoulder that you are doing the shoulderstand from. Start with the shoulderstand and wait until you''re at the top of the bounce. Then push yourself to the front by pushing with your hands off of the line, roll over your back and finish the trick by landing in Korean.', 'If you are on the right shoulder try to thread your right arm through the leash so you don''t end up with the leash stuck on your shoulder.;Often you will slightly overrotate this trick and it can help to grab with both hands in front of you to stop the momentum.', null, null, null, 10, 6, 1, 0);
insert into tricks (id, given_name, technical_name, difficulty_tier, date_submitted, date_performed, original_performer, prerequisite_trick_ids, base_trick_ids, description, tips, video_link, video_start, video_end, start_position_id, end_position_id, status, flags) overriding system value values (324, 'Korean Roll', null, 2, '2022-01-01T00:00:00+00:00', null, null, '{}', '{}', 'Sit in Korean, grab the line with one hand in front of you and one hand behind you and let yourself fall to the side. Land back in Korean.', 'Start the movement while the line moves upwards; You can try this trick clipped into a hangover first; Sometimes called "Harry Potter Roll"', 'https://youtu.be/ksF8g5YrXY8?t=135', 135, 137, 6, 6, 1, 1);
insert into tricks (id, given_name, technical_name, difficulty_tier, date_submitted, date_performed, original_performer, prerequisite_trick_ids, base_trick_ids, description, tips, video_link, video_start, video_end, start_position_id, end_position_id, status, flags) overriding system value values (325, 'Mini-Fireflip', '180 Chest Roll from Korean', 5, '2022-01-01T00:00:00+00:00', '2021-01-01', 'Salomé Cholet', '{}', '{}', 'From Korean grab the line behind you and go into a Front Chest Roll. Land back in Korean looking at the other anchor.', null, 'https://youtu.be/rWqH_51ztQA?t=14839', 14839, 14843, 6, 6, 1, 1);
insert into tricks (id, given_name, technical_name, difficulty_tier, date_submitted, date_performed, original_performer, prerequisite_trick_ids, base_trick_ids, description, tips, video_link, video_start, video_end, start_position_id, end_position_id, status, flags) overriding system value values (326, 'Flow', 'Korean 360', 5, '2022-01-01T00:00:00+00:00', null, null, '{}', '{}', 'From Korean you grab the line with both hands behind you and then swing your far leg over the line twice to do a 360 landing back in Korean.', 'Practice the same movement from Sofa first (= Backside Panic).', 'https://www.youtube.com/watch?v=12HbVhoFloM', null, null, 6, 6, 1, 1);
insert into tricks (id, given_name, technical_name, difficulty_tier, date_submitted, date_performed, original_performer, prerequisite_trick_ids, base_trick_ids, description, tips, video_link, video_start, video_end, start_position_id, end_position_id, status, flags) overriding system value values (327, 'Petit Trick', null, 6, '2026-04-25T21:28:03.559615+00:00', '2022-02-01', 'Salomé Cholet', '{}', '{}', 'From Korean, grab the line in front of you with both hands. Shift your weight onto your arms, swing one leg over the line and start bringing it to the front. Lean backwards, release your front hand and swing the same leg as before back over the line. Finish sitting in Korean.', null, 'https://youtu.be/Nk-wk2kYRso?t=109', 109, 112, 6, 6, 1, 1);
insert into tricks (id, given_name, technical_name, difficulty_tier, date_submitted, date_performed, original_performer, prerequisite_trick_ids, base_trick_ids, description, tips, video_link, video_start, video_end, start_position_id, end_position_id, status, flags) overriding system value values (328, 'Richard Roll', 'Back Korean Roll BS 180', 11, '2022-01-01T00:00:00+00:00', '2021-01-01', 'Sakalomo', '{}', '{}', 'Do a Back Korean Roll, pass the front leg over the line to be in Sofa, pass the back leg over the line to end in Korean facing the other anchor.', null, 'https://youtu.be/7yLCyoHgUS0?t=694', 694, 698, 6, 6, 1, 0);
insert into tricks (id, given_name, technical_name, difficulty_tier, date_submitted, date_performed, original_performer, prerequisite_trick_ids, base_trick_ids, description, tips, video_link, video_start, video_end, start_position_id, end_position_id, status, flags) overriding system value values (329, 'Wolf Flip', 'Reverse Flowflip', 11, '2022-01-01T00:00:00+00:00', null, null, '{}', '{}', 'From Korean initiate a 360 BS spin to the front and simultaneously start a roll backwards, spin for a full 360 to land back in Korean after the roll is finished.', null, null, null, null, 6, 6, 1, 1);
insert into tricks (id, given_name, technical_name, difficulty_tier, date_submitted, date_performed, original_performer, prerequisite_trick_ids, base_trick_ids, description, tips, video_link, video_start, video_end, start_position_id, end_position_id, status, flags) overriding system value values (330, 'Wolf', 'Reverse Flow', 8, '2026-04-25T21:28:03.559615+00:00', null, null, '{}', '{}', 'From Korean, grab the line in front of you and pass one leg over the line twice (first behind you, at the end in front of you) to do a 360 spin. It is the inverse motion of a Flow.', null, 'https://youtu.be/d5GTyM0ReFE?t=45', 45, 50, 6, 6, 1, 1);
insert into tricks (id, given_name, technical_name, difficulty_tier, date_submitted, date_performed, original_performer, prerequisite_trick_ids, base_trick_ids, description, tips, video_link, video_start, video_end, start_position_id, end_position_id, status, flags) overriding system value values (331, 'Nasty Korean', 'Full Flare from Korean', 17, '2022-01-01T00:00:00+00:00', '2021-01-01', 'Sebastian Egger', '{}', '{}', 'Full Flare (see breakdancing) from Korean to Korean.', null, null, null, null, 6, 6, 1, 0);
insert into tricks (id, given_name, technical_name, difficulty_tier, date_submitted, date_performed, original_performer, prerequisite_trick_ids, base_trick_ids, description, tips, video_link, video_start, video_end, start_position_id, end_position_id, status, flags) overriding system value values (334, 'Chest Roll to Front Roll', null, 14, '2022-01-01T00:00:00+00:00', '2017-01-01', 'Guillaume Fontaine', '{146}', '{146}', 'Start by doing a Chest Roll and then do a Front Roll by pushing with one foot off the line.', null, 'https://youtu.be/O_E_2cB0Pcw?t=40', 40, 44, 2, 6, 1, 0);
insert into tricks (id, given_name, technical_name, difficulty_tier, date_submitted, date_performed, original_performer, prerequisite_trick_ids, base_trick_ids, description, tips, video_link, video_start, video_end, start_position_id, end_position_id, status, flags) overriding system value values (335, 'Backbounce Panic Roll', null, 8, '2022-01-01T00:00:00+00:00', null, null, '{322,126}', '{322}', 'From Backbounce swing one leg to other side and then perform a Panic Roll in the opposite direction.', null, 'https://www.youtube.com/watch?v=LPsuhcOZd0Q', null, null, 1, 6, 1, 0);
insert into tricks (id, given_name, technical_name, difficulty_tier, date_submitted, date_performed, original_performer, prerequisite_trick_ids, base_trick_ids, description, tips, video_link, video_start, video_end, start_position_id, end_position_id, status, flags) overriding system value values (336, 'Back Roll Twist', null, 8, '2022-01-01T00:00:00+00:00', null, null, '{}', '{337}', 'While doing the second half of a Back Roll, also turn once around the line, so do a Back Roll with a Korean Roll at the end.', 'For some people, this happens automatically when they try a Back Roll with bad timing. If you''re not one of those, try adding a Korean Roll in the second half of the Back Roll.', 'https://youtu.be/rWqH_51ztQA?t=3487', 3487, 3493, 1, 6, 1, 0);
insert into tricks (id, given_name, technical_name, difficulty_tier, date_submitted, date_performed, original_performer, prerequisite_trick_ids, base_trick_ids, description, tips, video_link, video_start, video_end, start_position_id, end_position_id, status, flags) overriding system value values (337, 'Back Roll from Back', null, 5, '2022-01-01T00:00:00+00:00', null, null, '{}', '{}', 'Choose a shoulder that you will roll over to do this trick and put the leash on the side of this shoulder. From Backbounce wait until you are at the very top of the bounce and then pull yourself back over the shoulder and land in Korean.', 'Have the leash on the same side as the shoulder you roll over.', 'https://youtu.be/9pi0GYhBvdo?t=13', 13, 19, 1, 6, 1, 0);
insert into tricks (id, given_name, technical_name, difficulty_tier, date_submitted, date_performed, original_performer, prerequisite_trick_ids, base_trick_ids, description, tips, video_link, video_start, video_end, start_position_id, end_position_id, status, flags) overriding system value values (338, 'Hammock Back Roll', null, 14, '2022-01-01T00:00:00+00:00', '2017-01-01', 'Guillaume Fontaine', '{128,337}', '{128}', 'Do a Hammock Roll and finish with a Back Roll in the same bounce.', null, 'https://youtu.be/Ej2ocABoNC4?t=22785', 22785, 22790, 1, 6, 1, 0);
