insert into tricks (id, given_name, technical_name, difficulty_tier, date_submitted, date_performed, original_performer, prerequisite_trick_ids, base_trick_ids, description, tips, video_link, video_start, video_end, start_position_id, end_position_id, status, flags) overriding system value values (372, 'Sofa Roll', null, 3, '2022-01-01T00:00:00+00:00', '2016-01-01', 'Samuel Volery', '{}', '{}', 'Sit in Sofa, grab the line with both hands and press the line against your butt/thighs. Then throw yourself forward or backward, initiating the roll. To stop the roll, extend your legs.', 'Leash to the side can help prevent bad falls; If you fall into a backlever position let go of the line in order to save your shoulders; You can practice this trick with a hangover clipped in to save energy and get familiar with the movement without fear of falling badly', 'https://www.youtube.com/watch?v=Ugw1gRm-T0U', null, null, 11, 11, 1, 1);
insert into tricks (id, given_name, technical_name, difficulty_tier, date_submitted, date_performed, original_performer, prerequisite_trick_ids, base_trick_ids, description, tips, video_link, video_start, video_end, start_position_id, end_position_id, status, flags) overriding system value values (373, 'Utinni Roll', 'Side Sofa Roll', 5, '2022-01-01T00:00:00+00:00', '2021-01-01', 'Michele Eibeck', '{}', '{372}', 'Start in Sofa. Both hands next to you (right or left) holding on to the line. Then do a Sofa Roll with your body leaning towards the line where your hands are. To land the trick put the hands back to normal as you would when sitting in Sofa.', null, 'https://www.instagram.com/p/CNYQEb4Jt1M/', null, null, 11, 11, 1, 0);
